param([ValidateSet('build','test','out','qkv')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-prefix-replay-projection-20260916';$seed='D:\projects\AIMA-public-native-rz-qk-20260916';$sha='010154e48f646940e6e1f70003da91f3488d12e9';$bundle='D:\projects\prefix-replay-projection-010154e.bundle'
function Verify-File([string]$Path,[string]$Hash){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Hash){throw ('Changed input: '+$Path)}}
Verify-File $bundle 'ce3a9f323c65b7f5d9e83657cce3e78a12444b3b0260b077ec95fabab6d44710'
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\prefix-replay-projection';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\prefix_replay_projection_selftest.cpp';$exe=Join-Path $build 'prefix-replay-projection.exe';$provenance=Join-Path $build 'build-provenance.json'
$sourceFiles=@($source,(Join-Path $repo 'native\providers\sm121_attention_capacity.h'))
foreach($dir in @('native\providers\moe_accumulator','native\providers\gdn','native\providers\ck_fmha','tests\native')){
 $sourceFiles+=@(Get-ChildItem (Join-Path $repo $dir) -Filter '*.h' -File|ForEach-Object {$_.FullName})
}
$sourceInputs=@($sourceFiles|Sort-Object -Unique|ForEach-Object {@{file=$_;sha256=(Get-FileHash $_ -Algorithm SHA256).Hash.ToLowerInvariant()}})
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; generated BF16 projection inputs with original ordered K16 arithmetic';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;product_dispatch_changed=$false;purpose='Store two or four coarse C64 prefix checkpoints without changing their matrix centers or bounds. An exact original prefix plus the final-minus-prefix center and error increment bounds the original suffix. Certify only a common BF16 endpoint; otherwise compact the exact original carry and continue the next disjoint K range. Compare full replay, checkpoint storage control, two-stage and four-stage pipelines including all producer, count reads and compaction costs. Verify GB10 captured BF16 outputs, full-replay raw endpoints, independent CPU carries, interval coverage, complete membership, guards and prepared source words. Native zero-C error assumption remains 2^-19; component only.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $link=Join-Path $build 'hipblaslt.lib';Copy-Item 'C:\Program Files\AMD\ROCm\7.1\lib\libhipblaslt.dll.a' $link
 $spec.link_inputs=@(@{file=$link;sha256=(Get-FileHash $link -Algorithm SHA256).Hash.ToLowerInvariant()})
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','-DQRT_CK_SM121_INTERPOLATED_EXP2=1','--offload-arch=gfx1151','-L',$build,$source,'-o',$exe,'-lhipblaslt');$timeout=180
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha){throw 'Build commit mismatch'}
 Verify-File $exe $meta.executable.sha256
 foreach($file in $meta.source_inputs){Verify-File $file.file $file.sha256}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$exe;$spec.arguments=@('--selftest');$timeout=240
 if($Action -eq 'out' -or $Action -eq 'qkv'){
  if($Action -eq 'out'){
   $x='D:\projects\AIMA-public-fa-out-20260911\build\fla-model-q7169-fa-out-r1\layer3-full-full_attention_gated_context-bf16.bin'
   $w='D:\projects\gb10-dense-out-weight-f4cb470e.bin';$ref='D:\projects\gb10-dense-out-q8192-f1239dae.bin'
   $hashes=@('5c9cefec4b17d9cf14055d82a5b97c62b6313601bf0f4c39f9f1ed8ae9cc6d65','f4cb470eeff400e05add65afc846ca49ae934455237609da4e3a2d58380f02ab','f1239dae1a3126ad53dfecd1362c9459eb296c1bfc4b58c26d3bc3dcf486e4fa')
  }else{
   $x='D:\projects\AIMA-public-exact-ab-20260910\build\fla-model-q7169-embeddingnorm-capture-r1\input-rmsnorm-bf16.bin'
   $w='D:\projects\AIMA-public-capture-20260910\build\layer0-weights-r1\qkv.bin';$ref='D:\projects\sm121-qkv-reference-9510d980.bin'
   $hashes=@('6c67321f81040780088a742070c48ab3023043b8ef9de71d1ed5a970a8fe9161','b06edcc9973be74f862d072f89a195e2eecea067ee615144be8510656122401f','9510d98057e047e7dd6f4e7b9b6010862e54e938d37bb854078c2de419f0bf37')
  }
  $paths=@($x,$w,$ref);$inputs=@(for($i=0;$i -lt 3;$i++){@{file=$paths[$i];sha256=$hashes[$i]}})
  foreach($file in $inputs){Verify-File $file.file $file.sha256}
  $spec.input_files=$inputs;$spec.arguments=@(('--'+$Action),$x,$w,$ref);$timeout=300
  $spec.model='D:\models\Qwen3.6-35B-A3B; captured projection inputs with original7169 plus first1023 repeated rows at q8192 component shape'
  $spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83'
  $spec.real_model_prompt=$false;$spec.reference_is_compute_input=$false
 }


}
$out=Join-Path $repo ('build\prefix-replay-projection-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Evidence already exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 8|ForEach-Object {$_.Substring(0,[Math]::Min(2000,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native diagnostic action failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;link_inputs=$spec.link_inputs;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $expected=if($Action -eq 'test'){24}else{4}
 if($reports.Count -ne $expected){throw 'Incomplete prefix replay reports'}
 foreach($r in $reports){
  if($r.bf16_mismatches -ne 0 -or $r.full_replay_raw_mismatches -ne 0 -or $r.prefix_and_suffix_undercoverage -ne 0 -or -not $r.redzones_pass -or -not $r.immutable_inputs -or -not $r.production_audit_work_parity -or -not $r.coarse_producer_raw_unchanged){throw 'Prefix replay correctness failed'}
 }
 foreach($file in $spec.input_files){Verify-File $file.file $file.sha256}
}
